// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.

public enum ApplicationEvent: Equatable, Hashable {

    case singleDelivery(destination: Data, sourceInterface: Data, plaintext: Data
    )
    case request(destination: Data, linkId: Data, requestId: Data, requester: Data?, pathHash: Data, rttMillis: UInt64, data: Data
    )
    case response(linkId: Data, requestId: Data, data: Data
    )
    case responseSegment(linkId: Data, requestId: Data, segmentIndex: UInt64, totalSegments: UInt64, data: Data
    )
    case resourceAvailable(linkId: Data, hash: Data, metadata: Data?, resource: ResourceDescriptor
    )
    case resourceSegment(linkId: Data, originalHash: Data, segmentIndex: UInt64, totalSegments: UInt64, metadata: Data?, data: Data
    )
    case resourceNeedsDecompression(linkId: Data, hash: Data, stream: Data, uncompressedDataBytes: UInt64
    )
    case channelMessage(linkId: Data, messageType: UInt16, data: Data
    )
    case linkDelivery(linkId: Data, sourceInterface: Data, plaintext: Data, localDestination: Data?, arrivedAtMillis: UInt64
    )





}

